g":"KC04","mark":"X","diameter_mm":10,"count":7,"cut_length_m":2.35,"weight_kg":10.154320987654321,"note":"Lưới theo X, bước <=200; lớp bảo vệ 25 mm"},{"id":"R0248","element_id":"ST2","drawing":"KC04","mark":"Y","diameter_mm":10,"count":13,"cut_length_m":1.05,"weight_kg":8.425925925925926,"note":"Lưới theo Y, bước <=200; lớp bảo vệ 25 mm"}],"sheets":[{"id":"DT00","page":1,"title":"Cơ sở dữ liệu và quy ước đo bóc"},{"id":"KT01","page":2,"title":"Mặt bằng kiến trúc tầng 1 - TL 1:100"},{"id":"KT02","page":3,"title":"Mặt bằng kiến trúc tầng 2 - TL 1:100"},{"id":"KT03","page":4,"title":"Mặt bằng kiến trúc tầng 3 - TL 1:100"},{"id":"KT20","page":5,"title":"Mặt đứng, mặt cắt A-A và bảng cửa"},{"id":"KC01","page":6,"title":"Mặt bằng móng TL 1:100; chi tiết F dạng sơ đồ"},{"id":"KC02","page":7,"title":"Cột và dầm điển hình mọi tầng"},{"id":"KC03","page":8,"title":"Sàn, nền và lỗ thang"},{"id":"KC04","page":9,"title":"Thang chữ U - mặt bằng và mặt cắt triển khai"},{"id":"KL01","page":10,"title":"Tổng hợp khối lượng và đối chiếu"}],"grid":{"x":[0,6.0,12],"y":[0,6.0,12.0,18]},"stair_void":{"x":0.125,"y":12.125,"w":2.4,"l":3.7},"room_zones":[],"totals":[{"work":"Đào hố móng","unit":"m3","value":34.992000000000004},{"work":"BT lót móng","unit":"m3","value":3.0720000000000014},{"work":"BT móng","unit":"m3","value":8.231999999999998},{"work":"BT cổ móng","unit":"m3","value":0.3375000000000001},{"work":"Lấp trả móng","unit":"m3","value":19.537500000000005},{"work":"BT cột","unit":"m3","value":7.1550000000000065},{"work":"Ván khuôn cột","unit":"m2","value":114.4800000000001},{"work":"BT dầm dưới sàn","unit":"m3","value":20.527499999999996},{"work":"Ván khuôn dầm","unit":"m2","value":237.53249999999997},{"work":"BT nền","unit":"m3","value":22.281250000000004},{"work":"BT sàn","unit":"m3","value":78.35130000000001},{"work":"Ván khuôn sàn","unit":"m2","value":577.365},{"work":"Chống thấm mái","unit":"m2","value":223.5625},{"work":"Xây tường ngoài","unit":"m3","value":90.68999999999996},{"work":"Trát tường","unit":"m2","value":1536.6900000000007},{"work":"Sơn tường","unit":"m2","value":1536.6900000000007},{"work":"Cửa D1","unit":"m2","value":7.92},{"work":"Cửa W1","unit":"m2","value":38.88},{"work":"Xây vách trong","unit":"m3","value":31.489500000000017},{"work":"Cửa D2","unit":"m2","value":35.28},{"work":"Lát nền","unit":"m2","value":599.7900000000001},{"work":"BT bản thang","unit":"m3","value":1.5815781485592169},{"work":"BT bậc thang","unit":"m3","value":0.9075000000000002},{"work":"BT chiếu nghỉ","unit":"m3","value":0.6336},{"work":"Lát bậc + cổ bậc","unit":"m2","value":18.26},{"work":"Lát chiếu nghỉ","unit":"m2","value":5.28},{"work":"Thép D12","unit":"kg","value":326.253221124801},{"work":"Thép D16","unit":"kg","value":2611.389629629629},{"work":"Thép D8","unit":"kg","value":1156.3851851851848},{"work":"Thép D10","unit":"kg","value":8221.604938271603}],"layout_variant":0,"project":{"address":"Lô P20, khu đất giả lập, Hải Phòng","owner":"Chủ đầu tư giả lập P20","region":"Hải Phòng","address_is_fictional":true},"dxf":{"file":"P20_ban_ve.dxf","units":"m","layout":"modelspace; levels arranged along X, spacing width+4m","element_id":"XDATA application ELEMENT_ID","layers":["GRID","WALL","OPENING","COLUMN","BEAM","FOOTING","STAIR","LABEL"],"scope":"Schematic plan geometry; PDF contains other details. Beam and footing reference layers are superimposed on plan."}}}]$housing_payload$::jsonb;
  r jsonb;
  owner_id integer;
  project_id_value integer;
  result_id integer;
  project_count integer;
  result_count integer;
  project_name text;
  existing_result jsonb;
  existing_confirmed timestamptz;
BEGIN
  IF jsonb_array_length(payload) <> 20 OR
     (SELECT count(DISTINCT item->>'house_id') FROM jsonb_array_elements(payload) item) <> 20 OR
     EXISTS (SELECT 1 FROM jsonb_array_elements(payload) item WHERE item->>'data_kind' IS DISTINCT FROM 'SYNTHETIC') THEN
    RAISE EXCEPTION 'Bộ dữ liệu không hợp lệ';
  END IF;
  SELECT user_id INTO owner_id FROM users WHERE email = 'synthetic-housing@import.invalid';
  IF owner_id IS NULL THEN
    INSERT INTO users(email, full_name, role, is_active, password_hash)
      VALUES ('synthetic-housing@import.invalid', 'Kho nhà giả lập', 'user', false, '!disabled')
      RETURNING user_id INTO owner_id;
  ELSIF EXISTS (SELECT 1 FROM users WHERE user_id=owner_id AND is_active) THEN
    RAISE EXCEPTION 'Tài khoản nhập dữ liệu đang hoạt động; dừng để kiểm tra';
  END IF;
  FOR r IN SELECT value FROM jsonb_array_elements(payload) LOOP
    project_name := '[SYNTHETIC:' || (r->>'house_id') || '] Hồ sơ nhà ở giả lập';
    SELECT count(*), min(project_id) INTO project_count, project_id_value FROM projects
      WHERE user_id=owner_id AND name=project_name;
    IF project_count > 1 THEN RAISE EXCEPTION 'Dự án trùng: %', project_name; END IF;
    IF project_count = 0 THEN
      INSERT INTO projects(user_id,name,address,excluded_materials)
        VALUES(owner_id,project_name,COALESCE(r#>>'{data,project,address}',''), '[]'::jsonb)
        RETURNING project_id INTO project_id_value;
    END IF;
    SELECT count(*), min(takeoff_id) INTO result_count, result_id FROM takeoff_results
      WHERE project_id=project_id_value AND result->>'kind'='synthetic_housing';
    IF result_count > 1 THEN RAISE EXCEPTION 'Kết quả trùng: %', project_name; END IF;
    IF result_count = 0 THEN
      INSERT INTO takeoff_results(project_id,file_id,result,layer_overrides,confirmed_at)
        VALUES(project_id_value,NULL,r,'{}'::jsonb,NULL)
        RETURNING takeoff_id INTO result_id;
    ELSE
      SELECT result, confirmed_at INTO existing_result, existing_confirmed FROM takeoff_results WHERE takeoff_id=result_id;
      IF existing_confirmed IS NOT NULL OR existing_result IS DISTINCT FROM r THEN
        RAISE EXCEPTION 'Kết quả đã được xác nhận hoặc khác dữ liệu nguồn: %', project_name;
      END IF;
    END IF;
    IF NOT EXISTS (SELECT 1 FROM takeoff_results WHERE takeoff_id=result_id AND result=r AND confirmed_at IS NULL) THEN
      RAISE EXCEPTION 'Không kiểm tra được kết quả: %', project_name;
    END IF;
  END LOOP;
  INSERT INTO audit_logs(action,detail) VALUES ('IMPORT_SYNTHETIC_HOUSING_SQL',
    jsonb_build_object('count',20,'data_kind','SYNTHETIC','file_links','metadata_only'));
END $housing_import$;
-- Xem số dòng và số lượng chi tiết trước COMMIT; lỗi ở trên sẽ hủy giao dịch.
SELECT p.name, t.result->>'data_kind' AS data_kind,
       jsonb_array_length(t.result#>'{data,quantities}') AS so_dong_tien_luong,
       jsonb_array_length(t.result->'files') AS so_tep_tham_chieu,
       t.confirmed_at
FROM projects p JOIN users u ON u.user_id=p.user_id
JOIN takeoff_results t ON t.project_id=p.project_id
WHERE u.email='synthetic-housing@import.invalid' AND t.result->>'kind'='synthetic_housing'
ORDER BY p.name;
COMMIT;
